package oepul.o6_17.common

# Gemeinsame Hilfsregeln für die Maßnahme „Humuserhalt und Bodenschutz auf
# umbruchsfähigem Grünland“ (SRL 2.17, Maßnahmencode 17).

cfg := data.o6_17_tables

year := input.farm.year

o6 := object.get(input, ["farm", "oepul", "o6_17"], {})

measures := {m | some m in object.get(input, ["farm", "oepul", "participating_measures"], [])}

parcels := object.get(input, ["land", "parcels"], [])

grassland_parcels := [p | some p in parcels; p.land_use == "grassland"]

use_type(p) := object.get(p, "grassland_use_type", "unknown")

use_types_by_id := {t.id: t | some t in cfg.grassland_use_types}

use_type_info(p) := use_types_by_id[use_type(p)]

codes(p) := {c | some c in object.get(p, "codes", [])}

parcel_measures(p) := {m | some m in object.get(p, "oepul_measures", [])}

slope(p) := object.get(p, "slope_percent", null)

slope_below_18(p) if {
	s := slope(p)
	is_number(s)
	s < cfg.premium_rates.base_slope_limit_percent
}

slope_from_18(p) if {
	s := slope(p)
	is_number(s)
	s >= cfg.premium_rates.base_slope_limit_percent
}

# GLÖZ 2, GLÖZ 4 oder GLÖZ 9 Umbruchsverbot auf dem Schlag.
gloez_ban(p) if {
	some s in cfg.obligation_lists.gloez_ploughing_ban_standards
	object.get(p, ["gloez_ploughing_ban", s.id], false) == true
}

normalize(s) := n if {
	l := lower(s)
	u := replace(replace(replace(replace(l, "ä", "ae"), "ö", "oe"), "ü", "ue"), "ß", "ss")
	n := replace(replace(trim_space(u), "-", "_"), " ", "_")
}

round2(x) := round(x * 100) / 100

round3(x) := round(x * 1000) / 1000

contract_start_year := object.get(o6, "contract_start_year", null)

exit_date := object.get(o6, "exit_date", null)

exited_in_or_before_year if {
	is_string(exit_date)
	to_number(substring(exit_date, 0, 4)) <= year
}

# Vertrag läuft im Antragsjahr (Beginn 2023, 2024 oder 2025, Ende 31.12.2028).
contract_active if {
	is_number(contract_start_year)
	contract_start_year <= year
	year <= to_number(substring(cfg.general_framework.contract_end_date, 0, 4))
	not exited_in_or_before_year
}

is_first_year if year == contract_start_year

in_measure(codes_any) if {
	some m in measures
	m in codes_any
}

default contract_active := false

package oepul.o6_17.eligibility

# Zugangs- und Teilnahmevoraussetzungen (Informationsblatt Kapitel 3 und 7,
# SRL 2.17 Zugangsvoraussetzungen, SRL 1.4, 1.6.1, 1.10.5.2, 1.12.1.1).

import data.oepul.o6_17.common
import data.oepul.o6_17.livestock

cfg := data.o6_17_tables

fw := cfg.general_framework

# Kombinationsverpflichtung: zeitgleich UBB, BIO oder BIO-Teilbetrieb.
combination_fulfilled if common.in_measure({m | some m in cfg.combination.farm_level_required_any_of})

grassland_area_ha := sum([p.area_ha | some p in common.grassland_parcels])

# Landwirtschaftliche Nutzfläche ohne Almweideflächen.
agricultural_area_excl_alpine_ha := sum([p.area_ha |
	some p in common.parcels
	p.land_use in {"arable", "grassland", "special_crop"}
])

grassland_share := grassland_area_ha / agricultural_area_excl_alpine_ha if agricultural_area_excl_alpine_ha > 0

min_grassland_area_ok if grassland_area_ha >= 2.0

grassland_share_ok if grassland_share >= 0.4

valid_start_year if {
	some cp in fw.contract_periods
	cp.start_year == common.contract_start_year
}

application_date := object.get(common.o6, "measure_application_date", null)

# Maßnahmenantrag bis 31.12. vor dem ersten Verpflichtungsjahr.
application_in_time if {
	is_string(application_date)
	is_number(common.contract_start_year)
	application_date <= sprintf("%d-12-31", [common.contract_start_year - 1])
}

legal_form := object.get(input, ["farm", "applicant", "legal_form"], "natural_person")

public_body_share := object.get(input, ["farm", "applicant", "public_body_share_percent"], null)

public_share_ok if public_body_share == null

public_share_ok if {
	is_number(public_body_share)
	public_body_share <= fw.public_body_max_share_percent
}

# Gebietskörperschaften sind für die Maßnahme 17 nicht zugelassen.
applicant_eligible if {
	legal_form != "public_body"
	public_share_ok
}

first_oepul_year := object.get(input, ["farm", "oepul", "first_oepul_participation_year"], null)

protected_cultivation_ha := object.get(input, ["land", "protected_cultivation_area_ha"], 0)

agricultural_area_incl_alpine_ha := sum([p.area_ha |
	some p in common.parcels
	p.land_use in {"arable", "grassland", "special_crop", "alpine_pasture"}
])

farm_min_size_met if protected_cultivation_ha >= fw.farm_minimum_size.protected_cultivation_min_ha

farm_min_size_met if agricultural_area_incl_alpine_ha + protected_cultivation_ha >= fw.farm_minimum_size.agricultural_area_min_ha

access_failures contains "combination_ubb_bio_missing" if not combination_fulfilled

access_failures contains "applicant_not_eligible" if not applicant_eligible

access_failures contains "min_grassland_2ha_first_year" if {
	common.is_first_year
	not min_grassland_area_ok
}

access_failures contains "grassland_share_40_percent_first_year" if {
	common.is_first_year
	not grassland_share_ok
}

access_failures contains "livestock_holding_first_year" if {
	common.is_first_year
	not livestock.is_livestock_holding
}

access_failures contains "invalid_contract_start_year" if {
	common.is_first_year
	not valid_start_year
}

access_failures contains "measure_application_late" if {
	common.is_first_year
	not application_in_time
}

access_failures contains "farm_minimum_size_first_oepul_year" if {
	common.year == first_oepul_year
	not farm_min_size_met
}

# Rechtsfolge: im 1. Jahr kein Vertrag, ab dem 2. Jahr keine Prämie im Jahr.
consequence := "no_contract" if {
	count(access_failures) > 0
	common.is_first_year
} else := "no_premium_in_application_year" if {
	count(access_failures) > 0
} else := "none"

access_requirements_met if count(access_failures) == 0

default access_requirements_met := false

package oepul.o6_17.general

# Allgemeine Teilnahmebedingungen mit Bezug zur Maßnahme 17 sowie 2026-Hinweise
# (Allgemeine Teilnahmebedingungen 5.4 bis 7.2; SRL 1.4.2, 1.6.3, 1.7;
# GSP-AV § 6; AMA-Hinweise 2026).

import data.oepul.o6_17.common
import data.oepul.o6_17.livestock

fw := data.o6_17_tables.general_framework

drought := data.o6_17_tables.drought_2026

day_ns := ((24 * 60) * 60) * 1000000000

days_between(a, b) := (time.parse_ns("2006-01-02", b) - time.parse_ns("2006-01-02", a)) / day_ns

# ---------------------------------------------------------------------------
# Höhere Gewalt (GSP-AV § 6): Meldung binnen drei Wochen ab Möglichkeit.

force_majeure_claims := object.get(input, ["farm", "oepul", "force_majeure_claims"], [])

claim_in_time(c) if days_between(c.able_to_notify_date, c.notification_date) <= fw.force_majeure.notification_period_days

case_row(id) := r if {
	some r in fw.force_majeure.additional_cases
	r.id == id
}

claim_area_ok(c) if case_row(c.case_id).min_area_ha == null

claim_area_ok(c) if {
	is_number(case_row(c.case_id).min_area_ha)
	object.get(c, "area_ha", 0) >= case_row(c.case_id).min_area_ha
}

claim_area_ok(c) if not case_row(c.case_id)

force_majeure_recognisable contains c.claim_id if {
	some c in force_majeure_claims
	claim_in_time(c)
	claim_area_ok(c)
}

late_force_majeure_claims contains c.claim_id if {
	some c in force_majeure_claims
	not claim_in_time(c)
}

# ---------------------------------------------------------------------------
# Maßnahmenübernahme (Allgemeine Teilnahmebedingungen 6.3, SRL 1.7.3.1)

takeover := object.get(common.o6, "takeover", null)

takeover_deadline := sprintf("%d-%s", [common.year, fw.takeover.deadline_month_day_2023_2028]) if {
	common.year in {2023, 2028}
} else := sprintf("%d-%s", [common.year, fw.takeover.deadline_month_day])

takeover_problems contains "deadline_missed" if {
	is_object(takeover)
	takeover.application_date > takeover_deadline
}

takeover_problems contains "taker_already_participating" if {
	is_object(takeover)
	object.get(takeover, "taker_previously_participating", false) == true
}

takeover_problems contains "expansion_over_50_percent" if {
	is_object(takeover)
	takeover.expansion_to_other_area_ha > takeover.taken_over_area_ha * fw.takeover.max_expansion_share
}

takeover_valid if {
	is_object(takeover)
	count(takeover_problems) == 0
}

# ---------------------------------------------------------------------------
# Maßnahmenwechsel: Maßnahme 17 ist nicht als Ausgangsmaßnahme vorgesehen.

conversion_from_o6_17_possible if {
	some c in fw.measure_conversions
	c.from == "17"
}

# ---------------------------------------------------------------------------
# Einstieg und letzte Beantragung

agl_application_possible if {
	common.contract_active
	common.year <= fw.last_agl_year
}

# ---------------------------------------------------------------------------
# Unterjährige Flächenweitergabe ohne Weiterführung: Code OP erforderlich.

violations contains v if {
	common.contract_active
	some p in common.parcels
	object.get(p, ["o6_17", "transferred_during_year"], false) == true
	object.get(p, ["o6_17", "recipient_continues_commitment"], false) == false
	not "OP" in common.codes(p)
	v := {"rule_id": "o6_17.general.intra_year_transfer_op_code", "parcel_id": p.parcel_id, "detail": "Weitergegebene Fläche ohne Weiterführung durch Übernehmer ist mit Code OP zu versehen"}
}

# Fläche außerhalb Österreichs ist nicht förderfähig.
violations contains v if {
	some p in common.parcels
	object.get(p, "located_in_austria", true) == false
	v := {"rule_id": "o6_17.general.parcels_in_austria", "parcel_id": p.parcel_id, "detail": "Flächen außerhalb Österreichs werden nicht gefördert"}
}

# ---------------------------------------------------------------------------
# Mindestbewirtschaftung auf Grünland (ausgenommen Biodiversitätsflächen).

is_biodiversity_area(p) if {
	some c in common.codes(p)
	startswith(c, "DIV")
}

mown_or_grazed(p) if count(object.get(p, ["operations", "cutting_dates"], [])) > 0

mown_or_grazed(p) if object.get(p, ["operations", "full_grazing"], false) == true

violations contains v if {
	common.contract_active
	some p in common.grassland_parcels
	common.use_type(p) != "bergmaehder"
	common.use_type_info(p).base_premium_possible == true
	not is_biodiversity_area(p)
	not mown_or_grazed(p)
	object.get(p, ["operations", "season_completed"], false) == true
	v := {"rule_id": "o6_17.general.minimum_management_grassland", "parcel_id": p.parcel_id, "detail": "Keine jährliche vollflächige Mahd mit Verbringung bzw. vollflächige Beweidung"}
}

violations contains v if {
	common.contract_active
	some p in common.grassland_parcels
	common.use_type(p) == "bergmaehder"
	object.get(p, ["operations", "last_full_mowing_year"], 0) < common.year - 1
	v := {"rule_id": "o6_17.general.minimum_management_bergmaehder", "parcel_id": p.parcel_id, "detail": "Bergmähder: mindestens alle 2 Jahre einmal vollflächige Mahd und Verbringen des Mähgutes"}
}

# ---------------------------------------------------------------------------
# Kombinationsmaßnahmen: zusätzliche Weiterbildungsverpflichtungen (Hinweis
# im Informationsblatt 6.4).

related_training_obligations contains {"measure": "1A/1B", "topic": "biodiversity", "min_hours": 3} if common.in_measure({"1A", "1B", "1B_TB"})

related_training_obligations contains {"measure": "1B", "topic": "organic", "min_hours": 5} if common.in_measure({"1B", "1B_TB"})

# ---------------------------------------------------------------------------
# Dürre 2026: Ernteverpflichtung auf Ackerflächen in den betroffenen Bezirken.

farm_state := object.get(input, ["farm", "region", "federal_state"], "")

parcel_district(p) := object.get(p, "district", object.get(input, ["farm", "region", "district"], ""))

parcel_state(p) := object.get(p, "federal_state", farm_state)

in_drought_relief_area(p) if {
	some r in drought.harvest_relief_districts
	r.federal_state == parcel_state(p)
	r.district in {"*", parcel_district(p)}
}

harvest_share(p) := object.get(p, ["operations", "harvest", "harvested_share_percent"], 100)

no_harvestable_crop_due_to_drought(p) if object.get(p, ["operations", "harvest", "no_harvestable_crop_due_to_drought"], false) == true

harvest_relief_2026(p) if {
	common.year == drought.application_year
	p.land_use == "arable"
	in_drought_relief_area(p)
	no_harvestable_crop_due_to_drought(p)
}

parcels_with_harvest_relief_2026 contains p.parcel_id if {
	some p in common.parcels
	harvest_relief_2026(p)
}

violations contains v if {
	some p in common.parcels
	p.land_use == "arable"
	not livestock.is_arable_fodder(p)
	harvest_share(p) < drought.min_harvest_share_percent
	not harvest_relief_2026(p)
	not object.get(p, ["operations", "harvest", "force_majeure_claim_id"], null) in force_majeure_recognisable
	v := {"rule_id": "o6_17.general.harvest_obligation_arable", "parcel_id": p.parcel_id, "detail": "Ernte und Verbringen des Erntegutes auf mindestens 85 % des Schlages nicht erfolgt"}
}

summary := {
	"force_majeure_recognisable": force_majeure_recognisable,
	"late_force_majeure_claims": late_force_majeure_claims,
	"takeover_valid": takeover_valid,
	"takeover_problems": takeover_problems,
	"conversion_from_o6_17_possible": conversion_from_o6_17_possible,
	"agl_application_possible": agl_application_possible,
	"related_training_obligations": related_training_obligations,
	"parcels_with_harvest_relief_2026": parcels_with_harvest_relief_2026,
}

default takeover_valid := false

default conversion_from_o6_17_possible := false

default agl_application_possible := false

package oepul.o6_17.obligations

# Förderverpflichtungen: Verzicht auf Grünlandumbruch, umbruchslose
# Erneuerung, Weiterbildung, Bodenuntersuchungen (Informationsblatt Kapitel
# 5.1, 6.1 bis 6.5; SRL 2.17 Förderverpflichtungen).

import data.oepul.o6_17.common

lists := data.o6_17_tables.obligation_lists

breakups(p) := object.get(p, ["o6_17", "grassland_breakups"], [])

reason_documentation_ok(r, _) if r.requires_documentation == false

reason_documentation_ok(r, e) if {
	r.requires_documentation == true
	object.get(e, "necessity_documented", false) == true
}

reason_measure_ok(r) if count(r.requires_measure_any_of) == 0

reason_measure_ok(r) if common.in_measure({m | some m in r.requires_measure_any_of})

ploughing_exception_applies(e) if {
	some r in lists.ploughing_exception_reasons
	r.id == object.get(e, "reason", "none")
	reason_documentation_ok(r, e)
	reason_measure_ok(r)
}

area_m2(e) := object.get(e, "area_m2", 0)

# Umbruch auf irgendeiner Grünlandfläche des Betriebes ohne Ausnahme.
violations contains v if {
	common.contract_active
	some p in common.grassland_parcels
	some e in breakups(p)
	e.type == "ploughing"
	not ploughing_exception_applies(e)
	v := {"rule_id": "o6_17.obligation.no_grassland_ploughing", "parcel_id": p.parcel_id, "detail": "Grünlandumbruch ohne zulässige Ausnahme"}
}

# Geringfügige Abweichungen gelten nur bis 300 m² je Einzelfläche nicht als Umbruch.
violations contains v if {
	common.contract_active
	some p in common.grassland_parcels
	some e in breakups(p)
	e.type == "minor_deviation"
	area_m2(e) > lists.minor_deviation_max_m2
	v := {"rule_id": "o6_17.obligation.minor_deviation_300m2", "parcel_id": p.parcel_id, "detail": "Geringfügige Abweichung über 300 m² gilt als Umbruch"}
}

# Aufschüttungen über 300 m² nur mit vorab eingeholter landesrechtlicher Bewilligung.
violations contains v if {
	common.contract_active
	some p in common.grassland_parcels
	some e in breakups(p)
	e.type == "fill"
	area_m2(e) > lists.minor_deviation_max_m2
	object.get(e, "state_permit_obtained", false) != true
	v := {"rule_id": "o6_17.obligation.fill_over_300m2_permit", "parcel_id": p.parcel_id, "detail": "Aufschüttung über 300 m² ohne vorab eingeholte landesrechtliche Bewilligung"}
}

# Keine Nutzung im Jahr der Aufschüttung: Beantragung als „Sonstige Grünlandflächen“.
violations contains v if {
	common.contract_active
	some p in common.grassland_parcels
	some e in breakups(p)
	e.type == "fill"
	object.get(e, "no_use_in_year", false) == true
	common.use_type(p) != "sonstige_gruenlandflaeche"
	v := {"rule_id": "o6_17.obligation.fill_without_use_sonstige_gruenland", "parcel_id": p.parcel_id, "detail": "Ungenutzte Fläche nach Aufschüttung ist als Sonstige Grünlandfläche zu beantragen"}
}

# Kein Acker-Grünland-Flächentausch.
violations contains v if {
	common.contract_active
	some p in common.parcels
	object.get(p, ["o6_17", "arable_grassland_swap"], false) == true
	v := {"rule_id": "o6_17.obligation.no_arable_grassland_swap", "parcel_id": p.parcel_id, "detail": "Acker-Grünland-Flächentausch ist nicht möglich"}
}

allowed_devices := {d.id | some d in lists.allowed_renewal_devices}

# Umbruchslose Grünlanderneuerung nur mit Saatstriegel, Schlitzdrillgerät, Walze, Wiesenegge.
violations contains v if {
	common.contract_active
	some p in common.grassland_parcels
	some d in object.get(p, ["o6_17", "renewal_devices_used"], [])
	not common.normalize(d) in allowed_devices
	v := {"rule_id": "o6_17.obligation.allowed_renewal_devices", "parcel_id": p.parcel_id, "detail": sprintf("Gerät %v ist für die umbruchslose Grünlanderneuerung nicht zulässig", [d])}
}

# ---------------------------------------------------------------------------
# Weiterbildung: mindestens 5 Stunden Grünlandbewirtschaftung bis 31.12.2025.

training_courses := object.get(common.o6, "training_courses", [])

person_still_counts(c) if object.get(c, "person_left_farm_date", null) == null

person_still_counts(c) if {
	d := object.get(c, "person_left_farm_date", null)
	is_string(d)
	d > lists.training.deadline
}

qualifying_course(c) if {
	c.topic == "grassland"
	c.person_role in {"applicant", "involved_person"}
	c.provider_recognized == true
	c.course_date >= lists.training.earliest_course_date
	c.course_date <= lists.training.deadline
	object.get(c, "counted_for_other_commitment", false) == false
	object.get(c, "counted_for_other_farm", false) == false
	person_still_counts(c)
}

training_hours_by_person[pid] := hours if {
	some c in training_courses
	pid := c.person_id
	hours := sum([x.hours | some x in training_courses; x.person_id == pid; qualifying_course(x)])
}

training_fulfilled if {
	some pid
	training_hours_by_person[pid] >= lists.training.min_hours
}

violations contains v if {
	common.contract_active
	common.year >= 2025
	not training_fulfilled
	v := {"rule_id": "o6_17.obligation.training_5h_grassland", "parcel_id": null, "detail": "Weiterbildung Grünlandbewirtschaftung (mind. 5 Stunden bis 31.12.2025) nicht nachgewiesen"}
}

# ---------------------------------------------------------------------------
# Bodenuntersuchungen: pro angefangene 5 ha förderfähige Grünlandfläche unter
# 18 % Hangneigung (Mehrfachantrag 2025) mindestens eine Bodenprobe.

basis_area_input := object.get(common.o6, "soil_sample_basis_area_ha", null)

computed_basis_area_ha := sum([p.area_ha |
	some p in common.grassland_parcels
	common.slope_below_18(p)
	not common.gloez_ban(p)
])

soil_sample_basis_area_ha := basis_area_input if {
	is_number(basis_area_input)
} else := computed_basis_area_ha if {
	common.year == lists.soil_sample.basis_application_year
}

required_soil_samples := ceil(common.round3(soil_sample_basis_area_ha) / lists.soil_sample.hectares_per_sample)

soil_samples := object.get(common.o6, "soil_samples", [])

required_parameters := {x | some x in lists.soil_sample_required_parameters}

allowed_methods := {m.id | some m in lists.soil_sample_allowed_methods}

valid_soil_sample(s) if {
	s.sample_date >= lists.soil_sample.earliest_sample_date
	s.lab_submission_date <= lists.soil_sample.lab_submission_deadline
	s.lab_accredited == true
	s.method in allowed_methods
	count(required_parameters - {x | some x in s.parameters}) == 0
	object.get(s, "received_with_transferred_parcel", false) == false
}

valid_soil_sample_count := count([s | some s in soil_samples; valid_soil_sample(s)])

soil_samples_fulfilled if valid_soil_sample_count >= required_soil_samples

violations contains v if {
	common.contract_active
	common.year >= 2025
	is_number(required_soil_samples)
	not soil_samples_fulfilled
	v := {"rule_id": "o6_17.obligation.soil_samples_per_5ha", "parcel_id": null, "detail": sprintf("Bodenproben: %d gültig, %d erforderlich", [valid_soil_sample_count, required_soil_samples])}
}

# Ergebnisse der Bodenproben sind im INVEKOS-GIS einzutragen.
violations contains v if {
	common.contract_active
	some s in soil_samples
	valid_soil_sample(s)
	object.get(s, "recorded_in_invekos_gis", false) != true
	v := {"rule_id": "o6_17.obligation.soil_sample_results_in_gis", "parcel_id": null, "detail": sprintf("Ergebnis der Bodenprobe %v nicht im INVEKOS-GIS erfasst", [object.get(s, "sample_id", "ohne ID")])}
}

missing_inputs contains "farm.oepul.o6_17.soil_sample_basis_area_ha" if {
	common.contract_active
	common.year > lists.soil_sample.basis_application_year
	not is_number(basis_area_input)
